<?php
declare(strict_types=1);
require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/workspace.php';$user=require_role(['farmer','buyer']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{record_order_review($user,(int)($_POST['order_id']??0),(int)($_POST['rating']??0),(string)($_POST['comment']??''));flash('success','Your verified-order review has been saved.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('reviews.php');}
$orders=fetch_all('SELECT o.id,o.reference_code,o.completed_at,IF(o.buyer_id=:u1,farmer.full_name,buyer.full_name) AS counterparty,r.rating,r.comment FROM orders o JOIN users buyer ON buyer.id=o.buyer_id JOIN users farmer ON farmer.id=o.farmer_id LEFT JOIN reviews r ON r.order_id=o.id AND r.reviewer_id=:u2 WHERE o.status="completed" AND (o.buyer_id=:u3 OR o.farmer_id=:u4) ORDER BY o.completed_at DESC',['u1'=>$user['id'],'u2'=>$user['id'],'u3'=>$user['id'],'u4'=>$user['id']]);workspace_open('Verified-order reviews','reviews');
?>
<section class="workspace-section"><div class="workspace-section-header"><div><h2>Reviews tied to completed trades</h2><p>Only participants in a completed order can review one another. No anonymous or seeded ratings are accepted.</p></div></div><?php if($orders===[]):?><div class="empty-state"><h3>No completed orders to review</h3><p>A review form appears after an order reaches Completed.</p></div><?php else:foreach($orders as $order):?><form method="post" class="form-grid review-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><div><strong><?= e($order['reference_code']) ?> · <?= e($order['counterparty']) ?></strong></div><label>Rating<select name="rating" required><option value="">Choose</option><?php for($rating=5;$rating>=1;$rating--):?><option value="<?= $rating ?>" <?= (int)$order['rating']===$rating?'selected':'' ?>><?= $rating ?> / 5</option><?php endfor;?></select></label><label>Trade feedback<textarea name="comment" maxlength="1000" rows="3"><?= e($order['comment']??'') ?></textarea></label><button class="button button-quiet" type="submit">Save review</button></form><?php endforeach;endif;?></section>
<?php workspace_close(); ?>
